"""Build project-image compositions from captured UI and exact workflow diagrams.

Usage: python3 preview/build-project-visuals.py /path/to/project-sources
Screenshot each .poster in project-gallery.html at its native dimensions.
"""
from pathlib import Path
import base64,sys,html,json
root=Path(__file__).resolve().parents[1]
sources=Path(sys.argv[1])
def image(name,cls=''):
    data=base64.b64encode((sources/(name+'.png')).read_bytes()).decode()
    return f'<img class="{cls}" src="data:image/png;base64,{data}">'
cards=[]
def card(id,title,sub,bg,ink,accent,content,kind='UI SCREENSHOT'):
    cards.append(f'<section class="poster" id="{id}" style="--bg:{bg};--ink:{ink};--accent:{accent}"><header><span>CACINIEP / {kind}</span><span class="palette"><i></i><b></b><em></em></span></header><h1>{title}</h1><p class="subtitle">{sub}</p>{content}<footer>{kind} · SOURCE-LINKED PROJECT VISUAL<span>{id.upper()}</span></footer></section>')
card('texada','TeXada','从自然语言与截图，到可检查的公式。','#091b30','#d7eaff','#51baff','<div class="shot tex">'+image('texada')+'</div>')
card('studio','TeXada Studio','编辑、审阅、编译，让文档修复有迹可循。','#08182a','#d7eaff','#4b9cf2','<div class="shot">'+image('studio')+'</div>')
card('launchgrid','LaunchGrid','应用、进程、剪贴板与网络，在一个 Mac 入口。','#242526','#fafafa','#789cd6','<div class="shot">'+image('launchgrid')+'</div>')
card('slides','slide-recipes','可编辑的商业表达，配方、排版与渲染检查。','#f3f0e8','#153b34','#295242','<div class="shot">'+image('slides')+'</div>','GENERATED PPTX EXAMPLES')
card('lang','Lang Master','把编程语言，放回词法、句法与语义的坐标里。','#191b27','#dce1fa','#7e9ff5','<div class="shot">'+image('lang')+'</div>','LIVE APP CAPTURE')
card('beancount','FinancialBeancount','让不同来源的账单，进入同一套账本。','#edf2e9','#2d5038','#7e9c71','<div class="video-flow"><div class="video-source"><strong>支付宝 / 微信 / 银行卡</strong><p>本地账单</p><div class="wave">CSV · XLSX · STATEMENTS</div></div><div class="arrow">→</div><div class="output"><small>LOCAL CONVERSION</small><h2>Beancount</h2><div>账单格式转换</div><div>重复记录处理</div><div>本地文件交付</div></div></div>','WORKFLOW DIAGRAM')
card('doctor','MiniCPM Network Doctor','小模型提问，工具取证；先观察，再诊断。','#102527','#e2ece5','#91c8b7','''<div class="protocol"><div class="command">$ minicpm-network-doctor<br><span>“npm install 从 registry.npmjs.org 下载时超时”</span></div><div class="evidence"><div><small>01 / DNS</small><h2>198.18.0.38</h2><p>resolve_dns · fake-IP mapping</p></div><div><small>02 / HTTP</small><h2>HTTP 200</h2><p>test_http · through proxy path</p></div></div><div class="observation">TCP 成功可能只是本地代理接受连接，不能单独证明上游可达。</div><div class="axis"><span>DNS</span><span>TCP</span><span>HTTP</span><span>TLS</span><span>READ-ONLY</span></div></div>''','DOCUMENTED RUN EXCERPT')
card('video','video2knowledge','让视频里的信息，成为能核对来源的笔记。','#f2f5f2','#173c37','#438a72','''<div class="video-flow"><div class="video-source"><span class="play">▷</span><strong>讲解 / 屏幕 / 板书</strong><p>ASR · 画面理解 · 音画融合</p><div class="wave">▂ ▅ ▃ ▆ ▂ ▇ ▃ ▅ ▂ ▆ ▃ ▅ ▂ ▇ ▂ ▄</div></div><div class="arrow">→</div><div class="output"><small>SOURCE-AWARE NOTES</small><h2>笔记与来源线索</h2><div>时间戳字幕</div><div>Markdown + HTML</div><div>按需生成 Anki</div><p>重要数字与公式保留人工核对。</p></div></div>''','WORKFLOW DIAGRAM')
cards.append('''<section class="poster sushi" id="sushi" style="--bg:#f4ece0;--ink:#3d2c20;--accent:#ee8435"><header><span>SUSHI / 溯时 · iOS</span><span class="palette"><i></i><b></b><em></em></span></header><div class="sushi-copy"><small>回转寿司 × 专注时间</small><h1>一盘寿司，<br>一段专注。</h1><p>从传送带上，<br>选一盘此刻刚好的分量。</p><div class="durations">5m · 15m · 30m · 60m</div><p class="small">完成的专注积成盘数，<br>时间也就有了看得见的份量。</p></div><div class="phones">'''+image('sushi-conveyor','phone p1')+image('sushi-timer','phone p2')+image('sushi-home','phone p3')+'''</div><footer>APP STORE SCREENSHOTS · CONVEYOR / TIMER / HOME<span>CHOOSE A PLATE. START HERE.</span></footer></section>''')
css='''*{box-sizing:border-box}body{margin:0;background:#ddd;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",Arial,sans-serif}.poster{width:1200px;height:680px;position:relative;background:var(--bg);color:var(--ink);overflow:hidden;padding:28px 40px;margin-bottom:20px}.poster:after{content:"";position:absolute;inset:14px;border:1px solid color-mix(in srgb,var(--ink) 15%,transparent);pointer-events:none}header,footer{display:flex;justify-content:space-between;font:11px monospace;letter-spacing:1.8px;align-items:center;opacity:.8}h1{font-size:42px;letter-spacing:-1px;font-weight:600;margin:18px 0 6px}.subtitle{margin:0;font-size:20px;opacity:.8}.palette{display:flex;gap:7px}.palette i,.palette b,.palette em{display:block;width:15px;height:15px;border-radius:50%;background:var(--accent)}.palette b{background:var(--ink)}.palette em{background:var(--bg);border:1px solid var(--ink)}footer{position:absolute;bottom:29px;left:40px;right:40px;font-size:9px;letter-spacing:1.2px}.shot{position:absolute;top:161px;left:55px;right:55px;bottom:63px;display:flex;justify-content:center;align-items:center}.shot img{display:block;max-width:100%;max-height:100%;object-fit:contain;border-radius:7px;box-shadow:0 14px 35px #0003}.shot.tex img{width:auto;height:100%}#codetics .shot img{width:100%;height:100%;object-fit:cover;object-position:center 45%}.protocol{margin-top:30px}.command{padding:22px 26px;border:1px solid #ffffff28;border-radius:8px;font:19px/1.8 monospace;background:#0002;color:var(--accent)}.command span{color:var(--ink);opacity:.85}.steps,.evidence{display:flex;gap:18px;margin-top:22px}.steps>div,.evidence>div{flex:1;padding:20px 24px;border:1px solid #ffffff28;border-radius:7px;background:#ffffff04}.steps small,.evidence small,.output small{font:11px monospace;letter-spacing:2px;color:var(--accent)}.steps strong{display:block;font:34px Georgia;margin-top:16px}.steps p,.evidence p{font-size:16px;opacity:.8;margin:12px 0 0}.axis{display:flex;justify-content:space-between;margin-top:25px;font:12px monospace;color:var(--accent);letter-spacing:1.6px}.evidence h2{font:32px monospace;margin:12px 0}.observation{font-size:20px;margin-top:22px}.video-flow{display:flex;align-items:center;gap:35px;margin:45px 10px}.video-source{background:#173c37;color:#dcebe3;border-radius:12px;width:500px;height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center}.play{font:76px Georgia;color:#a5c9af}.video-source strong{font-size:25px;font-weight:500}.video-source p{font-size:15px;color:#bdcfc5}.wave{font-size:22px;letter-spacing:4px;color:#9cc8ae}.arrow{font-size:40px}.output{flex:1}.output h2{font-size:29px;font-weight:500}.output div{font-size:20px;border-bottom:1px solid #173c3725;padding:10px 0}.output p{font-size:14px;opacity:.7}.sushi-copy{position:absolute;left:48px;top:112px}.sushi-copy small{font-size:17px;letter-spacing:3px;color:#a4683a}.sushi-copy h1{font:600 57px/1.3 "PingFang SC",sans-serif;margin:24px 0}.sushi-copy p{font-size:23px;line-height:1.7;color:#7d634f}.sushi-copy p.small{font-size:17px}.durations{font:18px monospace;color:#d77a37}.phone{position:absolute;width:199px;height:431px;object-fit:cover;border:4px solid #fcf9f3;border-radius:27px;box-shadow:0 20px 40px #725b4328}.p1{left:514px;top:146px;transform:rotate(-5deg)}.p2{left:741px;top:97px}.p3{left:965px;top:154px;transform:rotate(5deg)}'''
(root/'preview/project-gallery.html').write_text('<!doctype html><meta charset="utf-8"><style>'+css+'</style>'+''.join(cards))
print('Built',len(cards),'project compositions')
